import random

GROUP = "number_theory"
SKILL = "extremal_principle"

def count_ways(target, min_digit, max_digit):
    ways = [0] * (target + 1)
    ways[0] = 1

    for digit in range(min_digit, max_digit + 1):
        for i in range(target, digit - 1, -1):
            ways[i] += ways[i - digit]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_digit = rng.randint(1, 5)
    max_digit = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)
    check_max_count = 0
    for digit in range(min_digit, max_digit + 1):
        if digit <= target_sum:
            check_max_count += count_ways(target_sum - digit, min_digit, digit - 1)

    answer = count_ways(target_sum, min_digit, max_digit)

    # Modify the problem to require finding the threshold number of digits needed to reach the target sum.
    threshold_count = 0
    for i in range(min_digit, max_digit + 1):
        if count_ways(target_sum, min_digit, i) > 0:
            threshold_count = i
            break

    # Ensure the threshold_count is such that it's the smallest number of digits that can produce at least one valid combination.
    check_threshold_count = 0
    for i in range(min_digit, max_digit + 1):
        if count_ways(target_sum, min_digit, i) > 0:
            check_threshold_count = i
            break

    assert answer == check_max_count, f"answer={answer} check={check_max_count}"
    assert threshold_count == check_threshold_count, f"threshold_count={threshold_count} check_threshold_count={check_threshold_count}"

    problem = (
        f"Determine the smallest number of digits {min_digit} to {threshold_count} (inclusive) that must be used "
        f"to ensure a set of digits can be formed such that their maximum digit does not exceed the target sum {target_sum} "
        f"and all digits sum to exactly {target_sum}. State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "combinatorics"
SKILL = "induction"


def max_partition(target, min_x, max_x, min_y, max_y):
    if target == 0:
        return 0

    if target < min_x:
        return -1

    max_size = 0

    for x in range(min_x, max_x + 1):
        if x <= target:
            remaining_sum = target - x
            size = max_partition(remaining_sum, min_x, x - 1, min_y, max_y)
            if size != -1:
                max_size = max(max_size, size + 1)

    return max_size


def generate(seed):
    rng = random.Random(seed)

    min_x = rng.randint(1, 5)
    max_x = rng.randint(10, 20)
    min_y = rng.randint(1, 5)
    max_y = rng.randint(10, 20)
    target = rng.randint(5, 10)

    answer = max_partition(target, min_x, max_x, min_y, max_y)

    check = -1
    for x in range(min_x, max_x + 1):
        if x <= target:
            remaining_sum = target - x
            size = max_partition(remaining_sum, min_x, x - 1, min_y, max_y)
            if size != -1:
                check = max(check, 1 + size)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of points within a rectangle defined by x-coordinates ranging from {min_x} to {max_x} and y-coordinates ranging from {min_y} to {max_y} (inclusive). "
        f"What is the maximum number of distinct points that can be selected such that no x-coordinate exceeds the target sum {target} and all points sum to exactly {target} along the x-coordinate? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "combinatorics"
SKILL = "extremal_principle"

def count_ways(target, min_day, max_day):
    ways = [0] * (target + 1)
    ways[0] = 1

    for day in range(min_day, max_day + 1):
        if day > target:
            continue
        for i in range(target, day - 1, -1):
            ways[i] += ways[i - day]

    return ways[target]

def generate(seed):
    rng = random.Random(seed)

    min_day = rng.randint(1, 5)
    max_day = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the maximum number of days that can sum to target_sum without exceeding max_day.
    max_days = 0
    for day in range(min_day, max_day + 1):
        if count_ways(target_sum, min_day, day) > 0:
            max_days = day

    answer = count_ways(target_sum, min_day, max_days)
    assert answer == count_ways(target_sum, min_day, max_days), f"answer={answer} check={count_ways(target_sum, min_day, max_days)}"

    problem = (
        f"In a month where days can range from {min_day} to {max_day} (inclusive), "
        f"what is the maximum number of days that can sum to exactly {target_sum} without exceeding {max_days}? State only the integer."
    )
    return problem, str(answer)

